     7→using System.IdentityModel.Tokens.Jwt;
     8→using System.Security.Claims;
     9→using System.Security.Cryptography;
    10→using System.Text;
    11→
    12→namespace SampleDotNet6App.Services;
    13→
    14→/// <summary>
    15→/// User service implementation
    16→/// </summary>
    17→public class UserService : IUserService
    18→{
    19→    private readonly ApplicationDbContext _context;
    20→    private readonly IMapper _mapper;
    21→    private readonly ILogger<UserService> _logger;
    22→    private readonly IConfiguration _configuration;
    23→
    24→    public UserService(ApplicationDbContext context, IMapper mapper, ILogger<UserService> logger, IConfiguration configuration)
    25→    {
    26→        _context = context;
    27→        _mapper = mapper;
    28→        _logger = logger;
    29→        _configuration = configuration;
    30→    }
    31→
    32→    public async Task<AuthResponseDto?> AuthenticateAsync(LoginDto loginDto)
    33→    {
    34→        _logger.LogInformation("Authenticating user: {Username}", loginDto.Username);
    35→
    36→        var user = await _context.Users
    37→            .FirstOrDefaultAsync(u => (u.Username == loginDto.Username || u.Email == loginDto.Username) && u.IsActive);
    38→
    39→        if (user == null || !VerifyPassword(loginDto.Password, user.PasswordHash))
    40→        {
    41→            _logger.LogWarning("Authentication failed for user: {Username}", loginDto.Username);
    42→            return null;
    43→        }
    44→
    45→        var token = GenerateJwtToken(user);
    46→        var userDto = _mapper.Map<UserDto>(user);
    47→
    48→        return new AuthResponseDto
    49→        {
    50→            Token = token,
    51→            User = userDto
    52→        };
    53→    }
    54→
    55→    public async Task<UserDto> RegisterAsync(RegisterDto registerDto)
    56→    {
    57→        _logger.LogInformation("Registering new user: {Username}", registerDto.Username);
    58→
    59→        var user = _mapper.Map<User>(registerDto);
    60→        user.PasswordHash = HashPassword(registerDto.Password);
    61→
    62→        _context.Users.Add(user);
    63→        await _context.SaveChangesAsync();
    64→
    65→        return _mapper.Map<UserDto>(user);
    66→    }
    67→
    68→    public async Task<IEnumerable<UserDto>> GetAllUsersAsync()
    69→    {
    70→        _logger.LogInformation("Getting all users");
    71→
    72→        var users = await _context.Users
    73→            .Where(u => u.IsActive)
    74→            .OrderBy(u => u.Username)
    75→            .ToListAsync();
    76→
    77→        return _mapper.Map<IEnumerable<UserDto>>(users);
    78→    }
    79→
    80→    public async Task<UserDto?> GetUserByIdAsync(int id)
    81→    {
    82→        _logger.LogInformation("Getting user with ID: {UserId}", id);
    83→
    84→        var user = await _context.Users.FindAsync(id);
    85→        return user != null ? _mapper.Map<UserDto>(user) : null;
    86→    }
    87→
    88→    public async Task<UserDto?> GetUserByUsernameAsync(string username)
    89→    {
    90→        _logger.LogInformation("Getting user with username: {Username}", username);
    91→
    92→        var user = await _context.Users
    93→            .FirstOrDefaultAsync(u => u.Username == username && u.IsActive);
    94→
    95→        return user != null ? _mapper.Map<UserDto>(user) : null;
    96→    }
    97→
    98→    public async Task<bool> IsUsernameAvailableAsync(string username)
    99→    {
   100→        return !await _context.Users.AnyAsync(u => u.Username == username);
   101→    }
   102→
   103→    public async Task<bool> IsEmailAvailableAsync(string email)
   104→    {
   105→        return !await _context.Users.AnyAsync(u => u.Email == email);
   106→    }
   107→
   108→    private string HashPassword(string password)
   109→    {
   110→        using var sha256 = SHA256.Create();
   111→        var hashedBytes = sha256.ComputeHash(Encoding.UTF8.GetBytes(password));
   112→        return Convert.ToBase64String(hashedBytes);
   113→    }
   114→
   115→    private bool VerifyPassword(string password, string hash)
   116→    {
   117→        var hashedInput = HashPassword(password);
   118→        return hashedInput.Equals(hash);
   119→    }
   120→
